mapper.select:
with candidate as ( select ps.product_source_id, ps.company_name, ps.product_name, ps.coverage_category_code::text as coverage_category_code, case when #{gender} = 'M' then round(ps.monthly_premium_male, 0) when #{gender} = 'F' then round(ps.monthly_premium_female, 0) else null end as monthly_price, count(si.subscription_item_id) as subscriber_count from insurance.product_source ps left join public.subscription_item si on si.capsule_product_id = ps.product_source_id and si.plan_version = 'CURRENT' and si.item_status = 'ACTIVE' and coalesce(si.effective_end_at, TIMESTAMPTZ '9999-12-31 00:00:00+00') > now() left join public.subscription s on s.subscription_id = si.subscription_id and s.subscription_status = 'ACTIVE' where ps.coverage_category_code::text in
#{code}
and exists ( select 1 from public.capsule_product cp where cp.capsule_product_id = ps.product_source_id ) group by ps.product_source_id, ps.company_name, ps.product_name, ps.coverage_category_code, case when #{gender} = 'M' then round(ps.monthly_premium_male, 0) when #{gender} = 'F' then round(ps.monthly_premium_female, 0) else null end ), ranked as ( select product_source_id, company_name, product_name, coverage_category_code, monthly_price, subscriber_count, row_number() over ( partition by coverage_category_code order by subscriber_count desc, product_source_id asc ) as category_rank from candidate where monthly_price is not null and monthly_price > 0 ) select product_source_id, company_name, product_name, coverage_category_code, monthly_price, subscriber_count, category_rank from ranked where category_rank <= 3 order by coverage_category_code asc, category_rank asc
